public static List<Integer> findSteppingNumbers(int low, int high) {
        List<Integer> result = new ArrayList<>();
        if (low < 0 || high < 0) return result;

        Queue<Integer> que = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            que.offer(i);
        }

        while (!que.isEmpty()) {
            int num = que.poll();
            if (num >= low && num <= high) {
                result.add(num);
            }
            if (num == 0 || num > high) continue;
            int lastDigit = num % 10;
            if (lastDigit > 0) {
                que.offer(num * 10 + (lastDigit - 1));
            }
            if (lastDigit < 9) {
                que.offer(num * 10 + (lastDigit + 1));
            }
        }

        Collections.sort(result);
        return result;
    }

public static int countDigitOne(int n) {
    if (n <= 0) return 0;

    int result = 0;
    long factor = 1;
    while (factor <= n) {
        long current = n / (factor * 10) * factor;
        long ahead = n % factor;
        long curDigit = (n / factor) % 10;

        if (curDigit == 0) {
            result += current;
        } else if (curDigit == 1) {
            result += current + ahead + 1;
        } else {
            result += current + factor;
        }

        factor *= 10;
    }

    return result;
}

