public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Arrays to store the lengths of continuous 1s in horizontal, vertical, diagonal, and anti-diagonal directions
    int[] horizontal = new int[n];
    int[] vertical = new int[m];
    int[] diagonal = new int[m + n - 1];
    int[] antiDiagonal = new int[m + n - 1];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Update horizontal length
                horizontal[j] = (j > 0 ? horizontal[j - 1] : 0) + 1;
                // Update vertical length
                vertical[i] = (i > 0 ? vertical[i - 1] : 0) + 1;
                // Update diagonal length
                diagonal[i + j] = (i > 0 && j > 0 ? diagonal[i + j - 1] : 0) + 1;
                // Update anti-diagonal length
                antiDiagonal[i - j + n - 1] = (i > 0 && j < n - 1 ? antiDiagonal[i - j + n - 2] : 0) + 1;

                // Update the maximum length
                maxLength = Math.max(maxLength, horizontal[j]);
                maxLength = Math.max(maxLength, vertical[i]);
                maxLength = Math.max(maxLength, diagonal[i + j]);
                maxLength = Math.max(maxLength, antiDiagonal[i - j + n - 1]);
            } else {
                // Reset lengths if current cell is 0
                horizontal[j] = 0;
                vertical[i] = 0;
                diagonal[i + j] = 0;
                antiDiagonal[i - j + n - 1] = 0;
            }
        }
    }

    return maxLength;
}

