    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int r = 0, c = 0, d = 0;

    while (d < result.length) {
        result[d++] = mat[r][c];
        if ((r + c) % 2 == 0) { // Moving up
            if (c == cols - 1) {
                r++;
            } else if (r == 0) {
                c++;
            } else {
                r--;
                c++;
            }
        } else { // Moving down
            if (r == rows - 1) {
                c++;
            } else if (c == 0) {
                r++;
            } else {
                r++;
                c--;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    char[] digits = Integer.toString(n).toCharArray();

    // Find the first digit that is smaller than a digit next to it
    int i;
    for (i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1 (no greater rearrangement possible)
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of digits[i] but greater than digits[i]
    int j;
    for (j = digits.length - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the position i
    Arrays.sort(digits, i + 1, digits.length);

    // Convert the sorted digits back to an integer
    long result = Long.parseLong(new String(digits));

    // Check if the result is within the range of int
    if (result > Integer.MAX_VALUE) {
        return -1;
    }

    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        generateNumbers(n, 0, new StringBuilder(), result);
        return result;
    }

private static void generateNumbers(int n, int cur, StringBuilder sb, List<String> result) {
        if (cur > n / 2) {
            if (n % 2 == 1) {
                if (sb.length() > 1 && sb.charAt(0) == '0') {
                    return;
                }
                result.add(sb.toString() + getMid(sb) + sb.reverse().toString());
            } else {
                result.add(sb + sb.reverse().toString());
            }
            sb.reverse();
            return;
        }
        generateNumbers(n, cur + 1, sb.append('0'), result);
        sb.setLength(sb.length() - 1);
        generateNumbers(n, cur + 1, sb.append('1'), result);
        sb.setLength(sb.length() - 1);
        generateNumbers(n, cur + 1, sb.append('6'), result);
        sb.setLength(sb.length() - 1);
        generateNumbers(n, cur + 1, sb.append('8'), result);
        sb.setLength(sb.length() - 1);
        generateNumbers(n, cur + 1, sb.append('9'), result);
        sb.setLength(sb.length() - 1);
    }

private static String getMid(StringBuilder sb) {
        if (sb.length() % 2 == 0) {
            return "";
        }
        int mid = sb.length() / 2;
        return sb.charAt(mid) == '6' ? "9" : "6";
    }

public static boolean isBoomerang(int[][] points) {
    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Calculate the area of the triangle formed by the points
    int area = x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2);

    // The points form a boomerang if the area is not zero
    return area != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("The index must be a positive integer.");
    }

    int[] uglyNumbers = new int[n];
    uglyNumbers[0] = 1;
    int index2 = 0, index3 = 0, index5 = 0;
    int nextMultipleOf2 = 2;
    int nextMultipleOf3 = 3;
    int nextMultipleOf5 = 5;
    int nextUglyNumber = 1;

    for (int i = 1; i < n; i++) {
        nextUglyNumber = Math.min(nextMultipleOf2, Math.min(nextMultipleOf3, nextMultipleOf5));
        uglyNumbers[i] = nextUglyNumber;

        if (nextUglyNumber == nextMultipleOf2) {
            index2++;
            nextMultipleOf2 = uglyNumbers[index2] * 2;
        }
        if (nextUglyNumber == nextMultipleOf3) {
            index3++;
            nextMultipleOf3 = uglyNumbers[index3] * 3;
        }
        if (nextUglyNumber == nextMultipleOf5) {
            index5++;
            nextMultipleOf5 = uglyNumbers[index5] * 5;
        }
    }

    return nextUglyNumber;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxEnergy = 1;
    int currentEnergy = 1;

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentEnergy++;
            maxEnergy = Math.max(maxEnergy, currentEnergy);
        } else {
            currentEnergy = 1;
        }
    }

    return maxEnergy;
}

public static List<Integer> lexicalOrder(int n) {
        List<Integer> result = new ArrayList<>();
        for (int i = 1; i < 10; i++) {
            helper(result, i, n);
        }
        return result;
    }

private static void helper(List<Integer> result, int current, int n) {
        if (current > n) {
            return;
        }
        result.add(current);
        for (int i = 0; i < 10; i++) {
            int next = current * 10 + i;
            if (next > n) {
                return;
            }
            helper(result, next, n);
        }
    }

public static int calculateUniqueSum(int[] nums) {
    Map<Integer, Integer> countMap = new HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    // Create an array to store the minimum number of perfect squares for each number up to n
    int[] dp = new int[n + 1];

    // Base case: The minimum number of perfect squares to sum up to 0 is 0
    dp[0] = 0;

    // Fill the dp array for each number from 1 to n
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // Initialize with the maximum possible (i.e., i == 1 + 1 + ... + 1)
        for (int j = 1; j * j <= i; j++) {
            dp[i] = Math.min(dp[i], dp[i - j * j] + 1);
        }
    }

    // The answer for n will be stored in dp[n]
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder(word).reverse();
        result.append(reversedWord).append(" ");
    }
    return result.toString().trim();
}
